_QPAT = iter("BDACADBCCBADDACB" * 20)


def Q(prompt, opts, a, whys, steps, concept, skill, hint, feedback="", diagram="", alt="", remap=True):
    """4-option MC. opts: 4 texts with the correct one at index a; whys: reasons for the 3 wrong options in order.
    The correct option is then placed at the next position of a balanced A-D pattern (remap=True)."""
    assert len(opts) == 4 and len(whys) == 3 and 0 <= a <= 3
    if remap:
        right = opts[a]
        wrongs = [o for i, o in enumerate(opts) if i != a]
        a = "ABCD".index(next(_QPAT))
        opts = list(wrongs)
        opts.insert(a, right)
    wr = iter(whys)
    choices = [C(o, correct=True) if i == a else C(o, why=next(wr)) for i, o in enumerate(opts)]
    if isinstance(steps, str):
        steps = [S("Work it out", text=steps)]
    return MC(prompt, choices, steps, concept=concept, skill=skill, hint=hint, feedback=feedback,
              diagram=diagram, diagram_alt=alt)


def N(prompt, answer, steps, concept, skill, hint, tol=0, unit="", feedback="", diagram="", alt=""):
    if isinstance(steps, str):
        steps = [S("Work it out", text=steps)]
    return NUM(prompt, answer, steps, tolerance=tol, unit=unit, concept=concept, skill=skill, hint=hint,
               feedback=feedback, diagram=diagram, diagram_alt=alt)


