PAT1 = "DBDACACCBDCBACBDCABADBABCDBCADDACCDABBDAACABDBBADC"
PAT2 = "CADBDACBADB"


def _mk(pat):
    it = iter(pat)

    def R(prompt, right, wrongs, whys, steps, concept, skill, hint, diagram="", alt=""):
        """Mock MC: the correct option goes to the next position of the balanced pattern."""
        pos = "ABCD".index(next(it))
        opts = list(wrongs)
        opts.insert(pos, right)
        return Q(prompt, opts, pos, whys, steps, concept, skill, hint, diagram=diagram, alt=alt, remap=False)
    return R


